'use strict';
const assert = require('node:assert/strict');
const C = require('./core.js');
let checks = 0;
function check(name, test) { test(); checks += 1; console.log('OK ' + name); }
check('Os quatro alvos e horários correspondem ao brief', () => assert.deepEqual(C.targets.map(t => [t.name, t.time]), [['Lua', '19h10'], ['Saturno', '20h00'], ['M42', '21h15'], ['Plêiades', '22h00']]));
check('Sessão nova tem quatro pendentes', () => assert.deepEqual(C.counts({}), { pending: 4, seen: 0, unseen: 0 }));
let records = C.saveRecord({}, 'lua', 'seen', '  Região de sombra visível.  ');
check('Salvar visto preserva a nota sem espaços externos', () => { assert.equal(records.lua.status, 'seen'); assert.equal(records.lua.note, 'Região de sombra visível.'); });
records = C.saveRecord(records, 'saturno', 'unseen', 'Nuvens no momento da tentativa.');
check('Vistos, não vistos e pendentes têm contagens distintas', () => assert.deepEqual(C.counts(records), { pending: 2, seen: 1, unseen: 1 }));
check('Filtro por tipo encontra Saturno', () => assert.deepEqual(C.filterTargets(records, 'planet', 'all').map(t => t.id), ['saturno']));
check('Filtro por estado encontra somente vistos', () => assert.deepEqual(C.filterTargets(records, 'all', 'seen').map(t => t.id), ['lua']));
check('Filtros combinados retornam vazio sem misturar estados', () => assert.equal(C.filterTargets(records, 'nebula', 'seen').length, 0));
check('Filtro de pendentes retorna M42 e Plêiades', () => assert.deepEqual(C.filterTargets(records, 'all', 'pending').map(t => t.id), ['m42', 'pleiades']));
const edited = C.saveRecord(records, 'saturno', 'seen', 'Visto depois de uma abertura entre nuvens.');
check('Editar substitui resultado e nota sem alterar outro alvo', () => { assert.equal(edited.saturno.status, 'seen'); assert.equal(edited.lua.note, records.lua.note); assert.equal(records.saturno.status, 'unseen'); });
check('Serialização e leitura preservam todos os registros', () => assert.deepEqual(C.decode(C.encode(edited)), edited));
check('Armazenamento inicialmente vazio é aceito', () => assert.deepEqual(C.decode(null), {}));
check('Conteúdo corrompido é rejeitado', () => assert.throws(() => C.decode('não é JSON')));
check('Versão desconhecida é rejeitada', () => assert.throws(() => C.decode('{"version":9,"records":{}}')));
check('Estado salvo inválido é rejeitado', () => assert.throws(() => C.decode('{"version":1,"records":{"lua":{"status":"pending","note":"","updatedAt":"x"}}}')));
check('Alvo desconhecido não pode receber registro', () => assert.throws(() => C.saveRecord({}, 'venus', 'seen', '')));
check('Um resultado é obrigatório', () => assert.throws(() => C.saveRecord({}, 'lua', '', '')));
check('Nota opcional vazia é válida', () => assert.equal(C.saveRecord({}, 'm42', 'unseen', '').m42.note, ''));
check('Limite de 600 caracteres é aplicado', () => { assert.equal(C.saveRecord({}, 'lua', 'seen', 'a'.repeat(600)).lua.note.length, 600); assert.throws(() => C.saveRecord({}, 'lua', 'seen', 'a'.repeat(601))); });
const reset = C.removeRecord(edited, 'lua');
check('Voltar a pendente remove nota e resultado apenas do alvo', () => { assert.equal(C.getStatus(reset, 'lua'), 'pending'); assert.equal(reset.lua, undefined); assert.equal(reset.saturno.note, edited.saturno.note); assert.equal(edited.lua.status, 'seen'); });
check('Unicode e texto literal sobrevivem à persistência', () => { const special = C.saveRecord({}, 'pleiades', 'seen', 'Céu nítido ✨ <script>exemplo</script>'); assert.equal(C.decode(C.encode(special)).pleiades.note, special.pleiades.note); });
console.log('\n' + checks + ' verificações de lógica concluídas.');
